/**
 * Private Email product logo: the concept chosen by `PRIVATE_EMAIL_CONCEPT` in
 * `scripts/generate-logo-assets.mjs` (from `design/logo/private-email-concepts/`, built on
 * the master plane in `design/logo/inboxies-mark.svg`). One colour (the current text colour), on a 32-unit grid so
 * it stays legible at 14–40 px. The paths are generated by
 * `scripts/generate-logo-assets.mjs`; re-run it instead of editing them.
 */
export default function PrivateEmailLogo({
	size = 20,
	className = "",
	showTile = false,
	alwaysLight = false,
}: {
	size?: number;
	className?: string;
	showTile?: boolean;
	alwaysLight?: boolean;
}) {
	const markSize = showTile ? Math.round(size * 0.8) : size;
	const svgContent = (
		<svg
			width={markSize}
			height={markSize}
			viewBox="0 0 32 32"
			className={showTile ? "" : className}
			fill="none"
			stroke="currentColor"
			strokeLinejoin="round"
			strokeLinecap="round"
			xmlns="http://www.w3.org/2000/svg"
			style={alwaysLight ? { color: "#1F1F24" } : undefined}
			aria-hidden="true"
		>
			{/* logo:generated:private */}
			<path d="M 5.17 24.5 A 2 2 0 1 0 9.17 24.5 A 2 2 0 1 0 5.17 24.5 Z" fill="currentColor" />
			<path d="M 1.87 27.87 A 1.6 1.6 0 1 0 5.07 27.87 A 1.6 1.6 0 1 0 1.87 27.87 Z" fill="currentColor" />
			<path d="M 7.64 9.63 L 28.52 1.67 A 1.92 1.92 0 0 1 30.97 4.19 L 22.86 23.66 A 1.24 1.24 0 0 1 20.92 24.13 L 16.86 20.71 L 14.33 23.93 A 0.99 0.99 0 0 1 12.58 23.49 L 11.18 15.45 L 7.23 11.61 A 1.2 1.2 0 0 1 7.64 9.63 Z" strokeWidth={1.532} />
			<path d="M 6.87 10.72 L 8.76 10.92 L 18.13 10.9 L 30.01 2.66 M 30.01 2.66 L 14.84 17.18 L 14.35 18 L 13.88 20.21 M 20.05 12.16 L 21.6 22.29 L 21.92 24.4 M 30.01 2.66 L 30.56 2.11" strokeWidth={1.277} />
			<path d="M 14.64 18.88 L 15.77 17.71 L 16.46 17.94 L 20.18 21.6 L 20.18 22.25 L 19.56 22.87 L 16.86 20.71 L 14.33 23.93 A 0.99 0.99 0 0 1 13.4 24.29 Z" fill="currentColor" />
			{/* /logo:generated:private */}
		</svg>
	);

	if (showTile) {
		return (
			<div
				className={`inline-flex items-center justify-center overflow-hidden ${
					alwaysLight
						? "bg-white border border-gray-200 shadow-sm"
						: "bg-kumo-base border border-kumo-line shadow-sm"
				} ${className}`}
				style={{ width: size, height: size, borderRadius: size * 0.22 }}
			>
				{svgContent}
			</div>
		);
	}

	return svgContent;
}
